import React, { useState } from "react";
import { Link } from "react-router-dom";
import "./Navbar.css";
import logo from "../assets/logo.png";
import cartIcon from "../assets/cart.png";

const Navbar = () => {
  const [menu, setMenu] = useState("shop");
  const [mobileMenuOpen, setMobileMenuOpen] = useState(false);
  const cartCount = 3; // Replace with actual cart state

  return (
    <nav className="navbar">
      <div className="navbar-left">
        <img src={logo} alt="logo" className="logo" />
        <ul className={`nav-menu ${mobileMenuOpen ? "active" : ""}`}>
          <li onClick={() => { setMenu("shop"); setMobileMenuOpen(false); }}>
            <Link to="/" className="link">Shop</Link>
            {menu === "shop" && <hr />}
          </li>
          <li onClick={() => { setMenu("about"); setMobileMenuOpen(false); }}>
            <Link to="/about" className="link">About</Link>
            {menu === "about" && <hr />}
          </li>
          <li onClick={() => { setMenu("contact"); setMobileMenuOpen(false); }}>
            <Link to="/contact" className="link">Contact</Link>
            {menu === "contact" && <hr />}
          </li>
        </ul>
      </div>

      <div className="navbar-right">
        <button className="login-btn">Login</button>
        <Link to="/cart" className="cart-icon-wrapper">
          <img src={cartIcon} alt="cart" className="cart-icon" />
          <span className="cart-count">{cartCount}</span>
        </Link>
        <div className="menu-toggle" onClick={() => setMobileMenuOpen(!mobileMenuOpen)}>
          ☰
        </div>
      </div>
    </nav>
  );
};

export default Navbar;
